/// <summary>
/// Continuing permission notice report controller
/// Class <c>METTransferOrderShippmentController</c> controller
/// </summary>
class METTransferOrderShippmentController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// constructor creates the instance for class
/// </summary>
/// <returns>constructor</returns>
public static METTransferOrderShippmentController construct()
{
    return new METTransferOrderShippmentController();
}

/// <summary>
/// Main method to run report
/// </summary>
/// <param name = "_args">_args</param>
static void main(Args _args)
{
    METTransferOrderShippmentController controller =
        METTransferOrderShippmentController::construct();

    PrintMgmtDocumentType type =  PrintMgmtDocumentType::METTOShipment;
    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(type);

    if (!printMgmtReportFormat.RecId)
    {
        select firstonly Name from printMgmtReportFormat
            where printMgmtReportFormat.DocumentType == type;
    }

    if (printMgmtReportFormat.Name)
    {
        controller.parmReportName(printMgmtReportFormat.Name);
    }
    else
    {
        controller.parmReportName(ssrsReportStr(METTransferOrderShippmentReport, Report));
    }
    METTransferOrderShippmentContract contract = controller.parmReportContract().parmRdpContract() as METTransferOrderShippmentContract;
    InventTransferTable transferTable = _args.record();
    contract.parmTransferId(transferTable.TransferId);

    controller.parmReportContract().parmRdpContract(contract);
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    controller.parmDialogCaption("@MET:METCPNotice");
    controller.startOperation();
}
